const active = new Set(['active', 'in progress', 'pending', 'ready', 'blocked', 'obsolete', 'cancelled', 'canceled']);
const priorityRank = value => {
  const p = String(value ?? '').trim().toLowerCase();
  if (['p0', 'urgent'].includes(p)) return 0;
  if (['p1', 'high'].includes(p)) return 1;
  if (['p2', 'medium'].includes(p)) return 2;
  if (['p3', 'low'].includes(p)) return 3;
  return 4;
};
const parseTime = value => {
  const ms = Date.parse(String(value ?? '').trim());
  return Number.isFinite(ms) ? ms : 0;
};
const triggerCooldown = value => {
  const trigger = String(value ?? '').trim().toLowerCase();
  if (trigger.includes('daily')) return 23 * 60 * 60 * 1000;
  if (trigger.includes('hour')) return 55 * 60 * 1000;
  if (trigger.includes('new/changed') || trigger.includes('event-driven')) return Infinity;
  return 55 * 60 * 1000;
};
const acceptanceIds = new Set(String($env.ASSISTANT_ACCEPTANCE_TASK_IDS || '').split(',').map(s => s.trim()).filter(Boolean));
const now = Date.now();
const seenTaskIds = new Set();
const eligible = [];
for (const [inputIndex, item] of $input.all().entries()) {
  const row = item.json;
  const status = String(row.Status ?? row.status ?? '').trim().toLowerCase();
  if (!active.has(status)) continue;
  const rowNumber = row.row_number ?? row.rowNumber;
  if (rowNumber === undefined || rowNumber === null || String(rowNumber).trim() === '') continue;
  const taskId = String(row['Task ID'] ?? row.task_id ?? row.ID ?? row.id ?? '').trim();
  if (!taskId || seenTaskIds.has(taskId)) continue;
  if (acceptanceIds.size && !acceptanceIds.has(taskId)) continue;
  if (taskId) seenTaskIds.add(taskId);
  const lastFollowUp = parseTime(row['Last Follow-up'] ?? row.last_follow_up);
  const updatedAt = parseTime(row['Updated At'] ?? row.updated_at);
  const changedSinceFollowUp = Boolean(updatedAt && (!lastFollowUp || updatedAt > lastFollowUp));
  const lastDisposition = String(row['Follow-up Disposition'] ?? row.follow_up_disposition ?? '').trim().toLowerCase();
  if (lastDisposition === 'delivery_failed' && !changedSinceFollowUp) continue;
  if (lastFollowUp && !changedSinceFollowUp) {
    const ageMs = Math.max(0, now - lastFollowUp);
    if (lastDisposition === 'execute' && ageMs < 4 * 60 * 60 * 1000) continue;
    if (lastDisposition === 'escalate' && ageMs < 24 * 60 * 60 * 1000) continue;
    const cooldownMs = triggerCooldown(row['Follow-up Trigger'] ?? row.follow_up_trigger);
    if (!Number.isFinite(cooldownMs) || ageMs < cooldownMs) continue;
  }
  eligible.push({
    pairedItem: { item: inputIndex },
    json: {
      ...row,
      _rowNumber: rowNumber,
      _runId: $execution.id,
      _readAt: new Date().toISOString(),
      _selection: { taskId, priorityRank: priorityRank(row.Priority ?? row.priority), changedSinceFollowUp }
    }
  });
}
eligible.sort((a, b) => {
  const byPriority = a.json._selection.priorityRank - b.json._selection.priorityRank;
  if (byPriority) return byPriority;
  const aLast = parseTime(a.json['Last Follow-up'] ?? a.json.last_follow_up);
  const bLast = parseTime(b.json['Last Follow-up'] ?? b.json.last_follow_up);
  if (aLast !== bLast) return aLast - bLast;
  return String(a.json._selection.taskId).localeCompare(String(b.json._selection.taskId));
});
return eligible.slice(0, 5);

const r = $json;
const text = (...keys) => keys.map(k => r[k]).find(v => v !== undefined && v !== null) ?? '';
const yes = v => /^(yes|true|1|approved|authorized)(\b|\s|—|-|:)/i.test(String(v).trim());
const value = String(text('Has Value','has_value','Value')).trim().toLowerCase();
const status = String(text('Status','status')).trim().toLowerCase();
const next = String(text('Next Action','next_action')).trim();
const sensitive = yes(text('Sensitive Permission','sensitive_permission'));
const cost = yes(text('New Cost','new_cost','Purchase Required'));
const ownerJudgment = yes(text('Owner Judgment','owner_judgment','Final Submission'));
const decisionRequired = yes(text('Outcome Decision Required','decision_required'));
let owner = String(text('Execution Owner','execution_owner','Owner','owner')).trim();
if (!owner && value !== 'no' && !['obsolete','cancelled','canceled'].includes(status)) owner = 'S/PM Orchestration';
let disposition = 'hold';
let reason = 'Waiting silently; no authorized executable next action.';
if (value === 'no' || ['obsolete','cancelled','canceled'].includes(status)) { owner = ''; disposition = 'archive'; reason = 'Task is obsolete or has no remaining value.'; }
else if (sensitive || cost || ownerJudgment || decisionRequired) { disposition = 'escalate'; reason = sensitive ? 'Sensitive permission required.' : cost ? 'New cost or purchase required.' : ownerJudgment ? 'Final owner-only judgment or submission required.' : 'Outcome-changing decision required.'; }
else if (yes(text('Authorized','authorized')) && next && String(text('Approval Status')).trim().toLowerCase() === 'approved' && String(text('Approval Reference')).trim() && Number.isFinite(Date.parse(String(text('Updated At')).trim())) && ('ac:' + String(text('Task ID','task_id','ID','id')) + ':' + String(text('Updated At')).trim()).length <= 128) { disposition = 'execute'; reason = 'Next action is clear and authorized.'; }
return { json: { ...r, 'Execution Owner': owner, _followUp: { disposition, reason, owner, nextAction: next, taskId: String(text('Task ID','task_id','ID','id')), runId: r._runId, readAt: r._readAt, approvalReference: String(text('Approval Reference')).trim(), revision: String(text('Updated At')).trim(), idempotencyKey: 'ac:' + String(text('Task ID','task_id','ID','id')) + ':' + String(text('Updated At')).trim() } } };

const source = $('Assign Owner and Decide').item.json;
const f = source._followUp;
const body = $json.body || {};
const receipt = body.receipt || {};
const httpOK = Number($json.statusCode) >= 200 && Number($json.statusCode) < 300;
const local = f.disposition === 'archive' || f.disposition === 'hold';
const bound = httpOK && body.ok === true && receipt.taskId === f.taskId && String(receipt.runId) === String(f.runId) && typeof receipt.id === 'string' && /^[A-Za-z0-9_-]{1,128}$/.test(receipt.id);
const accepted = local || (bound && (f.disposition !== 'execute' || (receipt.idempotency_key === f.idempotencyKey && receipt.approval_reference === f.approvalReference && ['accepted','completed'].includes(receipt.status))));
return {json:{...source, _delivery:{accepted, disposition: accepted ? f.disposition : 'delivery_failed', outcome: local ? (f.disposition === 'archive' ? 'Archived' : 'Held silently') : accepted ? 'Receipt ' + receipt.id : 'Delivery unverified; reconcile before retry', receiptId: accepted && !local ? receipt.id : null}}};
